package br.com.ajudamutua.crypto;
import br.com.ajudamutua.model.MemberPrivateData; import br.com.ajudamutua.repository.MemberPrivateDataRepository; import br.com.ajudamutua.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class CryptoRotationService {private final MemberPrivateDataRepository repo; private final SecretProtector crypto; private final CurrentUserService current; private final AuditService audit; public CryptoRotationService(MemberPrivateDataRepository r,SecretProtector c,CurrentUserService cu,AuditService a){repo=r;crypto=c;current=cu;audit=a;}
 @Transactional @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> rotate(){int count=0;Set<String> from=new HashSet<>();for(MemberPrivateData d:repo.findAll()){if(Objects.equals(d.getEncryptionKeyId(),crypto.keyId()))continue;String cpf=crypto.decrypt(d.getCpfCiphertext());String address=crypto.decrypt(d.getAddressCiphertext());from.add(String.valueOf(d.getEncryptionKeyId()));d.protect(crypto.encrypt(cpf),crypto.encrypt(address),crypto.keyId());count++;}repo.flush();audit.append(current.require().getId(),"PII_KEYS_ROTATED","MemberPrivateData",null,"{\"records\":"+count+",\"toKey\":\""+crypto.keyId()+"\"}");return Map.of("recordsReencrypted",count,"fromKeyIds",from,"toKeyId",crypto.keyId());}}
